import {DEMO,DURATIONS,POINTS,totals,ranked} from './model.js';
export const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const palette=['#6399e8','#eab76c','#83b3a5','#de9695','#a6a0ce','#8ebccc','#c1af77','#ca9cb4','#9db477','#8cabe0','#d6a285','#88b1b4'];
const paths={play:'<path d="m9 5 10 7-10 7Z"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',back:'<path d="M20 12H4m6-6-6 6 6 6"/>',edit:'<path d="m15 4 5 5-11 11H4v-5ZM12 7l5 5"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',clock:'<circle cx="12" cy="13" r="8"/><path d="M12 9v4l3 2M9 2h6"/>',file:'<path d="M14 2H6a2 2 0 0 0-2 2v16h16V8Zm0 0v6h6M8 12h8M8 16h6"/>',expand:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>'};
export const icon=n=>`<span class="icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${paths[n]||paths.file}</svg></span>`;
export const btn=(a,label,c='',attr='')=>`<button type="button" class="btn ${c}" data-action="${a}" ${attr}>${label}</button>`;
export function header(){return `<header class="wrap topbar"><button class="brand" data-action="home" aria-label="우리 반 퀴즈왕 처음 화면"><span class="brand-mark" aria-hidden="true">Q</span><span><strong>우리 반 퀴즈왕</strong><small>배운 것을 함께 나누는 마지막 5분</small></span></button><span class="lab">MADE BY <b>CHURRRI’S LAB</b></span><div class="top-actions"><button class="pill" data-action="help">${icon('file')}사용 방법</button></div></header>`;}
export const footer=()=>'<footer class="wrap footer"><span>© 2026 CHURRRI’S LAB · 우리 반 퀴즈왕</span><span>함께 생각하고, 함께 성장해요.</span></footer>';
export const back=()=>btn('home',icon('back')+'처음 화면','back');
export function card(q,manage=false){return `<article class="quiz-card"><div class="card-labels"><span class="chip ${q.builtIn?'blue':'gold'}">${q.builtIn?'예시 퀴즈':'내 퀴즈'}</span><span class="eyebrow" style="font-size:9px;letter-spacing:1px">${q.questions.length} QUESTIONS</span></div><h3>${esc(q.title)}</h3><p>${esc(q.subject||'우리 반 수업 퀴즈')} · ${q.questions.length}문제 · 정답당 10점</p><div class="card-bottom">${btn('setup',icon('play')+'시작하기','primary',`data-id="${esc(q.id)}"`)}<button class="pill" data-action="edit" data-id="${esc(q.id)}" aria-label="${esc(q.title)} ${q.builtIn?'복제하여 수정':'수정'}">${icon('edit')}</button>${manage?`<button class="pill" data-action="export" data-id="${esc(q.id)}" aria-label="${esc(q.title)} 내보내기">${icon('download')}</button>${!q.builtIn?`<button class="quiet" data-action="delete" data-id="${esc(q.id)}" aria-label="${esc(q.title)} 삭제">삭제</button>`:''}`:''}</div></article>`;}
export function home(data){const s=data.session;return `<main class="wrap">${s&&s.phase!=='finished'?`<section class="resume"><div><strong>이어서 함께 풀까요?</strong><p>${esc(s.quiz.title)} · ${s.index+1} / ${s.quiz.questions.length}문제 진행 중</p></div>${btn('resume','이어 하기 '+icon('arrow'),'soft')}</section>`:''}<section class="hero"><div class="hero-copy"><p class="eyebrow">OUR CLASS, ONE MORE QUESTION</p><h1>오늘 배운 걸,<br>함께 맞히는 <em>5분.</em></h1><p>수업의 마지막은 작은 퀴즈로 가볍게.<br>함께 의논하고, 정답 모둠에 10점을 더해 주세요.</p><div class="hero-actions">${btn('setup',icon('play')+'퀴즈 시작하기','primary',`data-id="${DEMO.id}"`)}${btn('new',icon('plus')+'퀴즈 만들기')}</div><p class="hero-note"><span>선생님 화면 하나로</span><span>모둠끼리 함께</span></p></div><div class="hero-art quiz-illustration"><img src="./assets/quiz-classroom.webp" alt="교실에서 친구들과 함께 손을 들고 퀴즈에 참여하는 학생들" width="1672" height="941" fetchpriority="high" decoding="async"></div></section><section><div class="section-title"><div><p class="eyebrow">READY FOR CLASS</p><h2>우리 반 퀴즈 서랍</h2><p>준비해 둔 퀴즈로 바로 시작해 보세요.</p></div>${btn('library',icon('grid')+'퀴즈 관리하기')}</div><div class="quiz-grid">${[DEMO,...data.quizzes.slice(-1)].map(q=>card(q)).join('')}<article class="quick-card"><span class="big-plus">＋</span><h3>오늘 수업에 딱 맞는 문제</h3><p>문제와 보기, 짧은 해설을 적어<br>우리 반만의 퀴즈를 준비해요.</p><button class="quiet" style="color:var(--blue);font-weight:800" data-action="new">새 퀴즈 만들기 →</button></article>${data.quizzes.length?'':`<article class="quick-card"><span class="big-plus">${icon('file')}</span><h3>집에서 준비하고, 학교에서</h3><p>퀴즈를 파일로 옮겨<br>어느 교실에서든 이어서 사용해요.</p><button class="quiet" style="color:var(--blue);font-weight:800" data-action="import">퀴즈 파일 가져오기 →</button></article>`}</div></section></main>`;}
export function library(quizzes){return `<main class="wrap">${back()}<div class="page-heading"><p class="eyebrow">YOUR QUIZ COLLECTION</p><h1>퀴즈 관리하기</h1><p>문제를 다듬고, 다시 사용하고, 다른 교실로 가져가요.</p></div><div class="section-title"><p>예시 1개 · 내 퀴즈 ${quizzes.length-1}개</p><div class="section-actions">${btn('import',icon('file')+'파일 가져오기')}${btn('new',icon('plus')+'새 퀴즈','primary')}</div></div><div class="quiz-grid">${quizzes.map(q=>card(q,true)).join('')}</div><p class="hint">예시 퀴즈를 수정하면 내 퀴즈로 복제해 저장해요. 퀴즈 파일에는 문제와 정답·해설만 담겨요.</p></main>`;}
export function setup(q,quizzes,settings){return `<main class="wrap">${back()}<div class="page-heading"><p class="eyebrow">LET’S GET READY</p><h1>우리 반, 몇 모둠인가요?</h1><p>모둠을 정하고 퀴즈를 시작해요. 맞힌 모둠마다 10점!</p></div><form id="setup-form" class="setup-grid"><section class="panel"><div class="form-row"><label class="field-label" for="quiz-choice">진행할 퀴즈</label><select class="field" id="quiz-choice">${quizzes.map(v=>`<option value="${esc(v.id)}" ${v.id===q.id?'selected':''}>${esc(v.title)} · ${v.questions.length}문제</option>`).join('')}</select></div><div class="form-row"><span class="field-label">모둠 수</span><div class="stepper"><button type="button" data-action="less-group" aria-label="모둠 수 줄이기" ${settings.names.length===2?'disabled':''}>−</button><strong>${settings.names.length}<small style="font-size:14px;color:#8290a1">모둠</small></strong><button type="button" data-action="more-group" aria-label="모둠 수 늘리기" ${settings.names.length===12?'disabled':''}>＋</button><span class="hint">2~12모둠</span></div><div class="group-inputs">${settings.names.map((n,i)=>`<label class="group-field" style="--team:${palette[i]}"><span class="dot" aria-hidden="true"></span><input class="field group-name" value="${esc(n)}" required maxlength="16" aria-label="${i+1}모둠 이름"></label>`).join('')}</div></div><div class="form-row" style="margin-bottom:0"><span class="field-label">문제별 생각 시간</span><div class="time-options">${DURATIONS.map(n=>`<button type="button" data-action="duration" data-value="${n}" class="${settings.duration===n?'selected':''}" aria-pressed="${settings.duration===n}">${n?n+'초':'타이머 끄기'}</button>`).join('')}</div><p class="hint">시간이 끝나도 정답은 선생님이 공개해요.</p></div></section><aside class="panel"><span class="chip blue">오늘의 퀴즈</span><h2 style="font-size:22px;letter-spacing:-.6px">${esc(q.title)}</h2><div class="summary-box"><div class="summary-line"><span>문제 수</span><strong>${q.questions.length}문제</strong></div><div class="summary-line"><span>정답 점수</span><strong>문제마다 +10점</strong></div><div class="summary-line"><span>모둠별 최고 점수</span><strong>${q.questions.length*POINTS}점</strong></div></div><p class="hint">학생들은 의논한 뒤 손가락이나 번호판으로 답을 보여 주세요. 선생님은 맞힌 모둠을 선택하면 돼요.</p><p id="setup-error" class="form-error" role="alert"></p><button class="btn primary full" type="submit">${icon('play')}퀴즈 시작!</button></aside></form></main>`;}
export function editor(draft,index){const q=draft.questions[index];return `<main class="wrap">${back()}<div class="page-heading"><p class="eyebrow">MAKE IT YOURS</p><h1>우리 반 퀴즈 만들기</h1><p>배운 내용을 네 개의 보기와 짧은 해설로 정리해요.</p></div>${draft.questions.some(v=>v.optionReasons)?'<div class="ai-review-note"><b>AI가 만든 초안이에요.</b> 문제마다 정답·해설·출제 근거를 확인하고, 필요한 부분을 고친 뒤 저장해 주세요.</div>':''}<div class="editor-meta"><label><span class="field-label">퀴즈 제목</span><input class="field" data-edit-field="title" maxlength="80" value="${esc(draft.title)}" placeholder="예: 6학년 과학 · 계절의 변화"></label><label><span class="field-label">과목·단원 <span style="font-weight:400;color:#9ba0a7">선택</span></span><input class="field" data-edit-field="subject" maxlength="80" value="${esc(draft.subject)}" placeholder="예: 과학 2단원"></label></div><div class="editor-layout"><nav class="editor-nav" aria-label="문제 목록">${draft.questions.map((v,i)=>`<button type="button" data-action="edit-question" data-index="${i}" class="${index===i?'selected':''}"><b>${String(i+1).padStart(2,'0')}번 문제</b><small>${esc(v.text||'새 문제를 적어 주세요')}</small></button>`).join('')}<button type="button" data-action="add-question">＋ 문제 추가</button></nav><section class="panel"><div class="section-title" style="margin-top:0"><span class="chip blue">QUESTION ${String(index+1).padStart(2,'0')}</span><select id="question-kind" aria-label="문제 종류" class="field" style="width:140px;font-size:12px;padding:7px 10px"><option value="lesson" ${q.kind==='lesson'?'selected':''}>학습 문제</option><option value="nonsense" ${q.kind==='nonsense'?'selected':''}>넌센스 문제</option></select></div><label class="field-label" for="edit-question-text">문제</label><textarea class="field" id="edit-question-text" data-edit-field="text" maxlength="500" placeholder="학생들과 함께 풀 문제를 적어 주세요.">${esc(q.text)}</textarea><p class="field-label" style="margin-top:23px">보기 네 개 <span style="font-size:11px;color:#8c97a4;font-weight:500">왼쪽 동그라미로 정답을 선택해요.</span></p><div class="options-edit">${q.options.map((v,i)=>`<div class="option-edit"><input type="radio" name="correct-answer" data-correct="${i}" ${q.correct===i?'checked':''} aria-label="${i+1}번 보기를 정답으로 선택"><span aria-hidden="true">${['①','②','③','④'][i]}</span><input class="field" data-option="${i}" maxlength="180" value="${esc(v)}" aria-label="${i+1}번 보기" placeholder="${i+1}번 보기"></div>`).join('')}</div><label class="field-label" for="edit-explanation" style="margin-top:23px">짧은 해설 <span style="font-weight:400;color:#9ba0a7">선택</span></label><textarea class="field" id="edit-explanation" data-edit-field="explanation" maxlength="1200" placeholder="정답을 공개할 때 함께 보여 줄 설명이에요.">${esc(q.explanation)}</textarea>${q.optionReasons?`<details class="ai-evidence"><summary>자료의 근거 · 보기별 설명 확인하기</summary>${q.sourceQuote?`<p><b>자료에서 찾은 근거</b></p><blockquote>${esc(q.sourceQuote)}</blockquote>`:'<p class="hint">넌센스 문제는 수업 자료와 별개의 말놀이예요.</p>'}<ol>${q.optionReasons.map(v=>`<li>${esc(v)}</li>`).join('')}</ol><p class="hint">아래 설명은 생성 당시의 참고 내용이에요. 문제나 보기를 수정했다면 정답·해설도 다시 확인해 주세요.</p></details>`:''}<div class="editor-tools"><div class="editor-actions">${btn('move-question-up','↑ 앞으로','',index===0?'disabled':'')}${btn('move-question-down','↓ 뒤로','',index===draft.questions.length-1?'disabled':'')}${btn('remove-question','문제 삭제','danger',draft.questions.length===1?'disabled':'')}</div><span class="hint">${index+1} / ${draft.questions.length}문제</span></div></section></div><p id="editor-error" class="form-error" role="alert"></p><div style="display:flex;justify-content:flex-end;gap:12px;margin-bottom:35px">${btn('library','목록으로')}${btn('save-quiz','퀴즈 저장하기 '+icon('arrow'),'primary')}</div></main>`;}
function gameTop(s){return `<div class="game-top">${back()}<span class="subtle">${esc(s.quiz.title)}</span><div class="top-actions"><span class="point-tag">정답당 10점</span><button class="pill" data-action="fullscreen">${icon('expand')}전체화면</button><button class="pill" data-action="help">사용 방법</button></div></div><div class="progress-track" aria-label="전체 ${s.quiz.questions.length}문제 중 ${s.index+1}번 문제"><span style="width:${(s.index+1)/s.quiz.questions.length*100}%"></span></div>`;}
function question(s){const q=s.quiz.questions[s.index],answer=s.phase==='answer';return `<div class="game-context"><span class="question-number"><b>${String(s.index+1).padStart(2,'0')}</b> / ${String(s.quiz.questions.length).padStart(2,'0')} 문제</span>${!answer&&s.timer.duration?`<div class="timer" id="timer">${icon('clock')}<span id="timer-text"></span><button id="timer-toggle" data-action="timer-toggle" aria-label="타이머 일시정지"></button><button data-action="timer-reset" aria-label="타이머 다시 시작">↺</button></div>`:`<span class="chip ${answer?'blue':''}">${answer?'정답을 확인해요':'시간을 넉넉하게 생각해요'}</span>`}</div><section class="question-panel"><span class="chip ${q.kind==='nonsense'?'gold':'blue'}">${q.kind==='nonsense'?'잠깐, 웃음 한 문제':'모둠끼리 의논해 보세요'}</span><h1 class="question-title">${esc(q.text)}</h1><div class="answer-options">${q.options.map((v,i)=>`<div class="answer-option ${answer?(q.correct===i?'correct':'dim'):''}"><span class="answer-label">${i+1}</span><span>${esc(v)}</span>${answer&&q.correct===i?'<span class="correct-mark" aria-label="정답">✓</span>':''}</div>`).join('')}</div>${answer?`<div class="explanation"><strong>정답 ${q.correct+1}번</strong><span>${esc(q.explanation||'모둠 친구들과 정답을 고른 이유도 이야기해 보세요.')}</span></div>`:''}</section><div class="game-actions">${answer?btn('award-screen','맞힌 모둠에 점수 주기 '+icon('arrow'),'primary'):btn('reveal','정답 공개하기 '+icon('arrow'),'primary')}</div><p class="game-note">${answer?'정답을 맞힌 모둠은 10점! 이제 모둠을 선택해 주세요.':'번호판이나 손가락으로 모둠의 답을 보여 주세요.'}</p>`;}
function awards(s){return `<div class="award-heading"><p class="eyebrow">QUESTION ${String(s.index+1).padStart(2,'0')} · TEAM POINTS</p><h1>정답을 맞힌 모둠은 어디인가요?</h1><p>맞힌 모둠을 모두 선택해 주세요. 모둠마다 <b>+10점</b>을 더해요.</p></div><div class="award-tools"><button class="quiet" data-action="select-all">전체 선택</button><span style="color:#ddd">|</span><button class="quiet" data-action="clear-selection">선택 해제</button></div><div class="award-grid">${totals(s).map((g,i)=>`<button class="award-card ${s.pending.includes(g.id)?'selected':''}" data-action="toggle-group" data-id="${g.id}" aria-pressed="${s.pending.includes(g.id)}" style="--team:${palette[i]}"><span class="selection-circle" aria-hidden="true">✓</span><strong><span class="dot" style="display:inline-block;margin-right:8px" aria-hidden="true"></span>${esc(g.name)}</strong><p>현재 ${g.score}점</p><span class="award-points">${s.pending.includes(g.id)?'+10점 선택됨':'모둠 선택하기'}</span></button>`).join('')}</div><div class="game-actions">${btn('answer-screen','정답 다시 보기')}${btn('confirm-awards',s.pending.length?`${s.pending.length}모둠 · 점수 확정하기`:'맞힌 모둠 없음 · 확정하기','primary')}</div><p class="game-note">점수는 확정 후에도 수정할 수 있어요. 같은 문제의 점수가 두 번 더해지지 않아요.</p>`;}
function scoreboard(s,final){return `<div class="score-heading">${final?'<div class="final-symbol" aria-hidden="true">🏆</div>':''}<p class="eyebrow">${final?'GREAT WORK, EVERYONE!':'OUR CLASS SCOREBOARD'}</p><h1>${final?'함께 풀어서 더 멋진 우리 반!':'지금 우리 반의 점수는?'}</h1><p>${final?`${s.quiz.questions.length}문제를 끝까지 함께 풀었어요. 모두 수고했어요!`:`${s.index+1}번 문제까지의 점수예요. 다음 문제도 함께 도전해요.`}</p></div><div class="score-list">${ranked(s).map(g=>{const idx=s.groups.findIndex(v=>v.id===g.id);return `<div class="score-row ${g.rank===1?'top':''}"><span class="rank">${g.joint?'공동<br>':''}${g.rank}위</span><span class="score-name">${esc(g.name)}</span><div class="bar-track" aria-hidden="true"><div class="bar-fill" style="--team:${palette[idx]};width:${g.score/(s.quiz.questions.length*POINTS)*100}%"></div></div><span class="score-total">${g.score}<small>점</small>${!final&&s.awards[s.index].includes(g.id)?'<em>이번 문제 +10</em>':''}</span></div>`;}).join('')}</div>${final?'<p class="final-description">점수가 같으면 공동순위예요. 함께 생각한 모든 모둠에게 박수!</p>':''}<div class="game-actions ${final?'final-actions':''}">${final?btn('restart','같은 퀴즈 다시 하기')+btn('library','다른 퀴즈 고르기','primary')+btn('home','처음 화면'):btn('edit-score','점수 수정')+btn('next',s.index===s.quiz.questions.length-1?'최종 결과 보기 '+icon('arrow'):'다음 문제 '+icon('arrow'),'primary')}</div>${final?'':'<p class="game-note">오답은 0점 · 정답은 10점 · 같은 점수는 공동순위</p>'}`;}
export function play(s){return `<main class="game-wrap">${gameTop(s)}${['question','answer'].includes(s.phase)?question(s):s.phase==='award'?awards(s):scoreboard(s,s.phase==='finished')}</main>`;}
